\documentclass{article}
\usepackage{amsmath}
\usepackage{amssymb}
\newcommand{\R}{\ensuremath{\mathbb{R}}}
\newcommand{\norm}[1]{\ensuremath{\lVert #1 \rVert}}
\newcommand{\inner}[2]{\ensuremath{\langle #1, #2 \rangle}}
\newcommand{\triple}[2]{\ensuremath{(#1, #2, #3)}}
\newcommand{\proj}[2]{\ensuremath{\mathrm{proj}_{#1}\, #2}}
\newcommand{\set}[1]{\ensuremath{\{ #1 \}}}
\title{Notes on Hilbert Spaces}
\begin{document}
\maketitle
Let $u, v \in \R^n$ with $\inner{u}{v} = 0$ and $\norm{u} = 1$.
The basis pair \inner{e_1}{e_2} spans the plane, and the full triple \triple{e_1}{e_2}{e_3} spans $\R^3$.
The stress \stress{250} exceeds the design limit, so the projection \proj{u}{v} is recomputed.
\end{document}

